-- Registered customers
-- SHOP.CUSTOMERS: SELECT
SELECT ID, NAME, EMAIL, COUNTRY_ID
FROM SHOP.CUSTOMERS;

-- SHOP.CUSTOMERS: SELECT by key
SELECT ID, NAME, EMAIL, COUNTRY_ID
FROM SHOP.CUSTOMERS
WHERE ID = :ID;

-- SHOP.ORDERS: SELECT
SELECT ID, CUSTOMER_ID, ORDER_DATE, TOTAL
FROM SHOP.ORDERS;

-- SHOP.ORDERS: SELECT by key
SELECT ID, CUSTOMER_ID, ORDER_DATE, TOTAL
FROM SHOP.ORDERS
WHERE ID = :ID;

-- SHOP.ORDER_LINES: SELECT
SELECT ORDER_ID, PRODUCT_ID, QTY
FROM SHOP.ORDER_LINES;

-- SHOP.ORDER_LINES: SELECT by key
SELECT ORDER_ID, PRODUCT_ID, QTY
FROM SHOP.ORDER_LINES
WHERE ORDER_ID = :ORDER_ID
  AND PRODUCT_ID = :PRODUCT_ID;

-- SHOP.PRODUCTS: SELECT
SELECT ID, NAME, PRICE
