-- Issued invoices
-- SHOP.INVOICES: SELECT
SELECT
    INVOICE_ID,
    CUSTOMER_ID,
    ISSUED_AT,
    AMOUNT,
    PAID,
    NOTES,
    PDF,
    DUE_IN
FROM SHOP.INVOICES;

-- SHOP.INVOICES: SELECT by key
SELECT
    INVOICE_ID,
    CUSTOMER_ID,
    ISSUED_AT,
    AMOUNT,
    PAID,
    NOTES,
    PDF,
    DUE_IN
FROM SHOP.INVOICES
WHERE INVOICE_ID = :INVOICE_ID;

-- CustomerOrders: query
SELECT c.ID, c.NAME, o.TOTAL, o.ORDER_DATE
FROM SHOP.CUSTOMERS c
JOIN SHOP.ORDERS o ON o.CUSTOMER_ID = c.ID
WHERE c.ID = :customer_id AND o.TOTAL > :min_total
ORDER BY o.ORDER_DATE DESC;
